t.script:
(function () {
    function wcfLog() {}
    function wcfWarn() {}
    function wcfElInfo(el) { return null; }
    function wcfInspect(label) {}

    function isProductUrlPath(path) {
        path = path || '';
        if (path.indexOf('/shop/product') === 0) return true;
        if (path.indexOf('/shop/') !== 0) return false;
        if (path.indexOf('/shop/category/') === 0 || path.indexOf('/shop/page/') === 0) return false;
        return path !== '/shop';
    }

    function isShopPage() {
        var path = window.location.pathname || '';
        var result = false;
        if (path === '/shop') result = true;
        else if (isProductUrlPath(path)) result = false;
        else result = path.indexOf('/shop/category/') === 0 || path.indexOf('/shop/page/') === 0;
        return result;
    }

    function getClearFiltersDefaultPath() {
        var path = window.location.pathname || '/shop';

        // Si estamos dentro de una categoría, limpiar filtros debe mantener
        // la categoría actual. En paginación o /shop simple volvemos a /shop.
        if (path.indexOf('/shop/category/') === 0) return path;
        return '/shop';
    }

    function isClearFiltersUrl(url) {
        if (!url || url.origin !== window.location.origin) return false;

        var path = url.pathname || '';
        if (isProductUrlPath(path)) return false;

        // En categorías, el botón nativo de Odoo puede apuntar a
        // /shop/category/..., no solo a /shop. La versión anterior no lo
        // reconocía y por eso se insertaba otro botón encima.
        return (
            path === '/shop' ||
            path === '/shop/' ||
            path.indexOf('/shop/category/') === 0 ||
            path.indexOf('/shop/page/') === 0
        );
    }

    function getNativeClearFiltersLinks() {
        var selectors = [
            '#o_wsale_offcanvas .accordion-item > a.btn[href]',
            '#products_grid_before .accordion-item > a.btn[href]',
            '.o_wsale_products_grid_before .accordion-item > a.btn[href]'
        ];
        var links = [];
        document.querySelectorAll(selectors.join(',')).forEach(function (link) {
            if (link.dataset.wcfClearFilters === '1') return;
            if (!link.querySelector('.oi.oi-close, .oi-close')) return;

            var text = (link.textContent || '').trim().toLowerCase();
            if (text.indexOf('filtro') === -1 && text.indexOf('filter') === -1) return;

            try {
                var url = new URL(link.getAttribute('href') || link.href, window.location.origin);
                if (!isClearFiltersUrl(url)) return;
            } catch (error) {
                return;
            }
            links.push(link);
        });
        return links;
    }

    function getClearFiltersTarget(originalLink) {
        var rawHref = originalLink
            ? (originalLink.getAttribute('href') || getClearFiltersDefaultPath())
            : getClearFiltersDefaultPath();
        var target;
        try {
            target = new URL(rawHref, window.location.origin);
        } catch (error) {
            target = new URL(getClearFiltersDefaultPath(), window.location.origin);
        }

        if (!isClearFiltersUrl(target)) {
            target = new URL(getClearFiltersDefaultPath(), window.location.origin);
        }

        // El destino siempre se deja sin query ni hash. Así se eliminan
        // tanto los filtros nativos como range_min_ID/range_max_ID.
        target.search = '';
        target.hash = '';
        return target.pathname || getClearFiltersDefaultPath();
    }

    function hasActiveCustomRangeFilters() {
        var params = new URLSearchParams(window.location.search);
        return getSources().some(function (item) {
            var minName = 'range_min_' + item.id;
            var maxName = 'range_max_' + item.id;

            if (params.has(minName)) {
                var currentMin = toNumber(params.get(minName), item.min);
                if (currentMin > item.min) return true;
            }
            if (params.has(maxName)) {
                var currentMax = toNumber(params.get(maxName), item.max);
                if (currentMax < item.max) return true;
            }
            return false;
        });
    }

    function configureClearFiltersLink(link, target) {
        if (!link) return;
        link.dataset.wcfClearFilters = '1';
        link.setAttribute('href', target);
        link.classList.remove('disabled');
        link.removeAttribute('aria-disabled');

        link.addEventListener('click', function (event) {
            event.preventDefault();
            event.stopPropagation();
            event.stopImmediatePropagation();
            window.location.assign(target);
        }, true);
    }

    function createSyntheticClearFiltersItem() {
        var target = getClearFiltersTarget(null);
        var item = document.createElement('div');
        item.className = 'accordion-item rounded-0 border-top-0 py-3 wcf-clear-filters-item';
        item.dataset.wcfClearFiltersItem = '1';

        var link = document.createElement('a');
        link.title = 'Eliminar filtros';
        link.className = 'btn btn-light d-flex align-items-center py-1';

        var small = document.createElement('small');
        small.className = 'mx-auto';
        var bold = document.createElement('b');
        bold.textContent = 'Eliminar filtros';
        small.appendChild(bold);

        var icon = document.createElement('i');
        icon.className = 'oi oi-close';
        icon.setAttribute('role', 'presentation');

        link.appendChild(small);
        link.appendChild(icon);
        item.appendChild(link);
        configureClearFiltersLink(link, target);
        return item;
    }

    function insertSyntheticClearFiltersItem() {
        if (!hasActiveCustomRangeFilters()) return;
        if (document.querySelector('.wcf-clear-filters-item')) return;

        var runtimeFilters = document.getElementById('wcf_runtime_range_filters');
        if (!runtimeFilters || !runtimeFilters.parentNode) return;

        var filtersContainer = runtimeFilters.parentNode;
        var clearItem = createSyntheticClearFiltersItem();

        // El slider custom puede estar situado después de atributos nativos
        // como "Marca". Insertar el botón justo antes del slider hacía que
        // apareciese a mitad del listado. Lo colocamos como primer bloque del
        // mismo contenedor para reproducir la posición superior del botón
        // original de Odoo, por encima de todos los filtros.
        filtersContainer.insertBefore(
            clearItem,
            filtersContainer.firstChild
        );
    }

    function getClearFiltersScope(element) {
        if (!element || !element.closest) return document.body;
        return (
            element.closest('#o_wsale_offcanvas') ||
            element.closest('#products_grid_before') ||
            element.closest('.o_wsale_products_grid_before') ||
            element.closest('form.js_attributes') ||
            element.parentElement ||
            document.body
        );
    }

    function dedupeClearFiltersItems() {
        var seenScopes = [];
        Array.prototype.slice.call(document.querySelectorAll('.wcf-clear-filters-item')).forEach(function (item) {
            var scope = getClearFiltersScope(item);
            if (seenScopes.indexOf(scope) !== -1) {
                item.remove();
                return;
            }
            seenScopes.push(scope);
        });
    }

    function replaceNativeClearFiltersButtons() {
        var nativeLinks = getNativeClearFiltersLinks();

        if (nativeLinks.length) {
            var groups = [];

            nativeLinks.forEach(function (originalLink) {
                var originalItem = originalLink.closest('.accordion-item') || originalLink;
                var scope = getClearFiltersScope(originalItem);
                var group = groups.find(function (candidate) {
                    return candidate.scope === scope;
                });
                if (!group) {
                    group = {scope: scope, links: []};
                    groups.push(group);
                }
                group.links.push(originalLink);
            });

            groups.forEach(function (group) {
                // Si antes creamos el botón sintético en este mismo bloque de
                // filtros, lo quitamos al aparecer el original de Odoo.
                Array.prototype.slice.call(group.scope.querySelectorAll('.wcf-clear-filters-item')).forEach(function (item) {
                    item.remove();
                });

                group.links.forEach(function (originalLink, index) {
                    var originalItem = originalLink.closest('.accordion-item');

                    // En categorías puede haber más de un botón nativo compatible
                    // dentro del mismo contenedor. Se conserva solo el primero.
                    if (index > 0) {
                        if (originalItem) originalItem.remove();
                        else originalLink.remove();
                        return;
                    }

                    var target = getClearFiltersTarget(originalLink);

                    if (originalItem) {
                        // Sustituimos el acordeón completo, no solo el enlace,
                        // para conservar exactamente estructura, márgenes y borde.
                        var replacementItem = originalItem.cloneNode(true);
                        replacementItem.classList.add('wcf-clear-filters-item');
                        replacementItem.dataset.wcfClearFiltersItem = '1';
                        var replacementLink = replacementItem.querySelector('a.btn[href]');
                        configureClearFiltersLink(replacementLink, target);
                        originalItem.replaceWith(replacementItem);
                    } else {
                        var replacementLinkOnly = originalLink.cloneNode(true);
                        configureClearFiltersLink(replacementLinkOnly, target);
                        originalLink.replaceWith(replacementLinkOnly);
                    }
                });
            });

            dedupeClearFiltersItems();
            return;
        }

        // Tras sustituir el original, las siguientes ejecuciones ya no lo
        // detectan como nativo. Si nuestro reemplazo existe, no duplicamos.
        if (document.querySelector('.wcf-clear-filters-item')) {
            dedupeClearFiltersItems();
            return;
        }

        // Caso que faltaba: solo hay filtros custom activos. Odoo no pinta
        // su botón, por lo que creamos uno idéntico en la misma ubicación.
        insertSyntheticClearFiltersItem();
        dedupeClearFiltersItems();
    }

    function cleanProductLinks() {
        if (!isShopPage()) {
            return;
        }
        var changed = 0;
        Array.prototype.slice.call(document.querySelectorAll('a[href*="/shop/"]')).forEach(function (link) {
            var href = link.getAttribute('href') || '';
            try {
                var url = new URL(href, window.location.origin);
                if (!isProductUrlPath(url.pathname)) return;

                // En ficha de producto no debe viajar nada del listado:
                // ni range_min_/range_max_, ni attribute_value vacíos, ni hash attribute_values.
                if (link.getAttribute('href') !== url.pathname) {
                    changed += 1;
                }
                link.setAttribute('href', url.pathname);
            } catch (error) {}
        });
    }

    function normalizeText(value) {
        return (value || '')
            .replace(/[\n\t]+/g, ' ')
            .replace(/[⌄⌃˅˄›‹⌵^v∨∧]/g, '')
            .replace(/\s+/g, ' ')
            .trim()
            .toLowerCase();
    }

    function toNumber(value, fallbackValue) {
        var text = String(value === undefined || value === null ? '' : value).replace(',', '.');
        var number = parseFloat(text);
        return Number.isFinite(number) ? number : fallbackValue;
    }

    function formatNumber(value) {
        var number = toNumber(value, null);
        if (number === null) return String(value || '0');
        return Number.isInteger(number) ? String(number) : String(number).replace('.', ',');
    }

    function findTextNode(text) {
        var wanted = normalizeText(text);
        var candidates = document.querySelectorAll('h1,h2,h3,h4,h5,h6,strong,b,label,button,span,div');
        for (var i = 0; i < candidates.length; i++) {
            var node = candidates[i];
            if (node.closest('#wcf_runtime_range_filters') || node.closest('#wcf_range_filters_data')) continue;
            if (normalizeText(node.textContent) === wanted) return node;
        }
        return null;
    }

    function findPriceBlock() {
        var title = findTextNode('Rango de precio');
        if (!title) return null;

        var current = title;
        for (var i = 0; i < 8 && current; i++) {
            if (current.querySelector && current.querySelector('input[type="range"]')) return current;
            current = current.parentElement;
        }
        return title.parentElement || title;
    }

    function getSources() {
        return Array.prototype.slice.call(document.querySelectorAll('#wcf_range_filters_data .wcf-range-source')).map(function (node) {
            return {
                id: node.dataset.id,
                name: node.dataset.name || '',
                min: toNumber(node.dataset.min, 0),
                max: toNumber(node.dataset.max, 100)
            };
        }).filter(function (item) {
            return item.id && item.name;
        });
    }


    function syncAccordionState(block, open) {
        // Bootstrap/Odoo debe ser el único responsable de alternar
        // .show, .collapsed y aria-expanded. Aquí solo guardamos
        // una clase auxiliar propia para estilos/estado interno.
        block.classList.toggle('wcf-open', !!open);
    }

    function buildBlock(item, params) {
        var minParamName = 'range_min_' + item.id;
        var maxParamName = 'range_max_' + item.id;
        var hasMinParam = params.has(minParamName);
        var hasMaxParam = params.has(maxParamName);
        var currentMin = hasMinParam ? toNumber(params.get(minParamName), item.min) : item.min;
        var currentMax = hasMaxParam ? toNumber(params.get(maxParamName), item.max) : item.max;

        if (currentMin < item.min) currentMin = item.min;
        if (currentMin > item.max) currentMin = item.max;
        if (currentMax < item.min) currentMax = item.min;
        if (currentMax > item.max) currentMax = item.max;
        if (currentMin > currentMax) {
            var tmp = currentMin;
            currentMin = currentMax;
            currentMax = tmp;
        }

        var selectedMin = currentMin;
        var selectedMax = currentMax;
        var isOpen = (currentMin > item.min) || (currentMax < item.max);
        var collapseId = 'wcf_range_filter_inner_' + item.id;

        var block = document.createElement('div');
        block.className = 'accordion-item wcf-range-filter' + (isOpen ? ' wcf-open' : '');
        block.dataset.wcfAttributeId = item.id;
        block.dataset.wcfAttributeName = item.name;

        var header = document.createElement('h6');
        header.className = 'accordion-header';

        var button = document.createElement('button');
        button.type = 'button';
        button.className = 'accordion-button px-0 bg-transparent shadow-none' + (isOpen ? '' : ' collapsed');
        button.setAttribute('data-bs-toggle', 'collapse');
        button.setAttribute('data-bs-target', '#' + collapseId);
        button.setAttribute('aria-controls', collapseId);
        button.setAttribute('aria-expanded', isOpen ? 'true' : 'false');

        var title = document.createElement('b');
        title.textContent = item.name;
        button.appendChild(title);
        header.appendChild(button);

        var collapse = document.createElement('div');
        collapse.id = collapseId;
        collapse.className = 'accordion-collapse collapse' + (isOpen ? ' show' : '');

        var body = document.createElement('div');
        body.className = 'wcf-range-body';

        var wrapper = document.createElement('div');
        wrapper.className = 'wcf-range-wrapper position-relative visible';

        var sliderSpace = document.createElement('div');
        sliderSpace.className = 'wcf-range-slider-space';

        var track = document.createElement('span');
        track.className = 'wcf-range-track';

        var fill = document.createElement('span');
        fill.className = 'wcf-range-fill';

        var minInput = document.createElement('input');
        minInput.type = 'range';
        minInput.className = 'form-range range-with-input wcf-range-slider wcf-range-min d-inline-block p-0 align-top';
        minInput.name = minParamName;
        minInput.min = String(item.min);
        minInput.max = String(item.max);
        minInput.step = '1';
        minInput.value = String(selectedMin);
        minInput.setAttribute('aria-label', item.name + ' mínimo');

        var maxInput = document.createElement('input');
        maxInput.type = 'range';
        maxInput.className = 'form-range range-with-input wcf-range-slider wcf-range-max d-inline-block p-0 align-top';
        maxInput.name = maxParamName;
        maxInput.min = String(item.min);
        maxInput.max = String(item.max);
        maxInput.step = '1';
        maxInput.value = String(selectedMax);
        maxInput.setAttribute('aria-label', item.name + ' máximo');

        var values = document.createElement('small');
        values.className = 'wcf-range-values d-flex justify-content-between mt-2';
        values.innerHTML = '<span class="opacity-75 opacity-100-hover mt-1">' + formatNumber(item.min) + '</span>' +
            '<span class="opacity-75 opacity-100-hover mt-1">' + formatNumber(item.max) + '</span>';

        var editors = document.createElement('div');
        editors.className = 'wcf-range-editors';

        var manualMinLabel = document.createElement('label');
        manualMinLabel.className = 'wcf-range-editor';
        var manualMinCaption = document.createElement('span');
        manualMinCaption.className = 'wcf-range-editor-label';
        var manualMinInput = document.createElement('input');
        manualMinInput.type = 'number';
        manualMinInput.className = 'wcf-range-number wcf-range-number-min';
        manualMinInput.min = String(item.min);
        manualMinInput.max = String(item.max);
        manualMinInput.step = '1';
        manualMinInput.value = String(selectedMin);
        manualMinInput.inputMode = 'numeric';
        manualMinInput.setAttribute('aria-label', 'Escribir mínimo para ' + item.name);
        manualMinLabel.appendChild(manualMinCaption);
        manualMinLabel.appendChild(manualMinInput);

        var separator = document.createElement('span');
        separator.className = 'wcf-range-editor-separator';
        separator.textContent = '–';
        separator.setAttribute('aria-hidden', 'true');

        var manualMaxLabel = document.createElement('label');
        manualMaxLabel.className = 'wcf-range-editor';
        var manualMaxCaption = document.createElement('span');
        manualMaxCaption.className = 'wcf-range-editor-label';
        var manualMaxInput = document.createElement('input');
        manualMaxInput.type = 'number';
        manualMaxInput.className = 'wcf-range-number wcf-range-number-max';
        manualMaxInput.min = String(item.min);
        manualMaxInput.max = String(item.max);
        manualMaxInput.step = '1';
        manualMaxInput.value = String(selectedMax);
        manualMaxInput.inputMode = 'numeric';
        manualMaxInput.setAttribute('aria-label', 'Escribir máximo para ' + item.name);
        manualMaxLabel.appendChild(manualMaxCaption);
        manualMaxLabel.appendChild(manualMaxInput);

        editors.appendChild(manualMinLabel);
        editors.appendChild(separator);
        editors.appendChild(manualMaxLabel);

        var manualError = document.createElement('div');
        manualError.className = 'wcf-range-manual-error';
        manualError.setAttribute('role', 'alert');
        manualError.textContent = 'Introduce valores entre ' + formatNumber(item.min) + ' y ' + formatNumber(item.max) + ', con el mínimo igual o inferior al máximo.';

        var applyButton = document.createElement('button');
        applyButton.type = 'button';
        applyButton.className = 'btn btn-outline-primary btn-sm wcf-range-apply';
        applyButton.textContent = 'Aplicar';

        function percent(value) {
            var total = item.max - item.min;
            if (!total) return 0;
            return ((value - item.min) / total) * 100;
        }

        function setManualValidity(valid) {
            manualMinInput.classList.toggle('wcf-range-number-invalid', !valid);
            manualMaxInput.classList.toggle('wcf-range-number-invalid', !valid);
            manualMinInput.setAttribute('aria-invalid', valid ? 'false' : 'true');
            manualMaxInput.setAttribute('aria-invalid', valid ? 'false' : 'true');
            manualError.classList.toggle('wcf-visible', !valid);
            applyButton.disabled = !valid;
        }

        function updateVisualState(activeSlider) {
            minInput.setAttribute('aria-valuetext', formatNumber(selectedMin));
            maxInput.setAttribute('aria-valuetext', formatNumber(selectedMax));

            var left = percent(selectedMin);
            var right = 100 - percent(selectedMax);
            fill.style.left = left + '%';
            fill.style.right = right + '%';

            minInput.style.zIndex = activeSlider === minInput ? '6' : '4';
            maxInput.style.zIndex = activeSlider === maxInput ? '6' : '5';
        }

        function syncFromSliders(activeSlider) {
            var minValue = toNumber(minInput.value, item.min);
            var maxValue = toNumber(maxInput.value, item.max);

            if (minValue > maxValue) {
                if (activeSlider === minInput) {
                    maxValue = minValue;
                    maxInput.value = String(maxValue);
                } else {
                    minValue = maxValue;
                    minInput.value = String(minValue);
                }
            }

            selectedMin = minValue;
            selectedMax = maxValue;
            manualMinInput.value = String(selectedMin);
            manualMaxInput.value = String(selectedMax);
            setManualValidity(true);
            updateVisualState(activeSlider);
        }

        function readManualRange() {
            var minText = String(manualMinInput.value || '').trim();
            var maxText = String(manualMaxInput.value || '').trim();
            var minValue = minText === '' ? null : Number(minText.replace(',', '.'));
            var maxValue = maxText === '' ? null : Number(maxText.replace(',', '.'));
            var valid = Number.isFinite(minValue) && Number.isFinite(maxValue) &&
                minValue >= item.min && minValue <= item.max &&
                maxValue >= item.min && maxValue <= item.max &&
                minValue <= maxValue;

            setManualValidity(valid);
            if (!valid) return null;
            return { min: minValue, max: maxValue };
        }

        function previewManualRange(activeManualInput) {
            var manualRange = readManualRange();
            if (!manualRange) return;

            selectedMin = manualRange.min;
            selectedMax = manualRange.max;
            minInput.value = String(selectedMin);
            maxInput.value = String(selectedMax);
            updateVisualState(activeManualInput === manualMinInput ? minInput : maxInput);
        }

        function removeNativeAttributeParamsForRange(params, attributeId) {
            var prefix = String(attributeId) + '-';
            ['attribute_value', 'attrib'].forEach(function (paramName) {
                var values = params.getAll(paramName);
                if (!values.length) return;
                params.delete(paramName);
                values.forEach(function (value) {
                    if (String(value).indexOf(prefix) !== 0) {
                        params.append(paramName, value);
                    }
                });
            });
        }

        function applyRange() {
            var nextParams = new URLSearchParams(window.location.search);
            removeNativeAttributeParamsForRange(nextParams, item.id);
            var minValue = selectedMin;
            var maxValue = selectedMax;

            if (minValue > maxValue) {
                var tmp = minValue;
                minValue = maxValue;
                maxValue = tmp;
            }

            if (minValue <= item.min) {
                nextParams.delete(minParamName);
            } else {
                nextParams.set(minParamName, String(minValue));
            }

            if (maxValue >= item.max) {
                nextParams.delete(maxParamName);
            } else {
                nextParams.set(maxParamName, String(maxValue));
            }

            if (!nextParams.has('search')) nextParams.set('search', '');
            if (!nextParams.has('order')) nextParams.set('order', '');
            window.location.href = window.location.pathname + '?' + nextParams.toString();
        }

        function applyManualRange() {
            var manualRange = readManualRange();
            if (!manualRange) {
                if (manualMinInput.getAttribute('aria-invalid') === 'true') manualMinInput.focus();
                return;
            }
            selectedMin = manualRange.min;
            selectedMax = manualRange.max;
            minInput.value = String(selectedMin);
            maxInput.value = String(selectedMax);
            updateVisualState(null);
            applyRange();
        }

        sliderSpace.appendChild(track);
        sliderSpace.appendChild(fill);
        sliderSpace.appendChild(minInput);
        sliderSpace.appendChild(maxInput);
        wrapper.appendChild(sliderSpace);
        wrapper.appendChild(values);
        wrapper.appendChild(editors);
        wrapper.appendChild(manualError);
        wrapper.appendChild(applyButton);
        body.appendChild(wrapper);
        collapse.appendChild(body);
        block.appendChild(header);
        block.appendChild(collapse);

        collapse.addEventListener('shown.bs.collapse', function () {
            syncAccordionState(block, true);
        });
        collapse.addEventListener('hidden.bs.collapse', function () {
            syncAccordionState(block, false);
        });

        minInput.addEventListener('input', function () { syncFromSliders(minInput); });
        maxInput.addEventListener('input', function () { syncFromSliders(maxInput); });
        minInput.addEventListener('change', applyRange);
        maxInput.addEventListener('change', applyRange);
        manualMinInput.addEventListener('input', function () { previewManualRange(manualMinInput); });
        manualMaxInput.addEventListener('input', function () { previewManualRange(manualMaxInput); });
        manualMinInput.addEventListener('keydown', function (event) {
            if (event.key === 'Enter') {
                event.preventDefault();
                applyManualRange();
            }
        });
        manualMaxInput.addEventListener('keydown', function (event) {
            if (event.key === 'Enter') {
                event.preventDefault();
                applyManualRange();
            }
        });
        applyButton.addEventListener('click', applyManualRange);

        syncFromSliders(null);
        syncAccordionState(block, isOpen);
        return block;
    }

    function getNativeAttributeBlock(node) {
        if (!node || !node.closest) return null;
        if (node.closest('#wcf_runtime_range_filters') || node.closest('#wcf_range_filters_data')) return null;
        if (node.closest('#o_wsale_price_range_option_inner')) return null;

        var block = node.closest(
            '.accordion-item, .o_wsale_attribute, .css_attribute_select, .js_attribute, .mb-3, .border-bottom'
        );
        if (block && !block.closest('#wcf_runtime_range_filters')) return block;

        var current = node.parentElement;
        for (var i = 0; i < 6 && current; i++) {
            if (current.id === 'wcf_runtime_range_filters' || current.id === 'wcf_range_filters_data') return null;
            if (current.querySelector && current.querySelector('[name="attrib"], [name="attribute_value"]')) return current;
            current = current.parentElement;
        }
        return null;
    }

    function hideBlock(block) {
        if (!block) return;
        if (block.id === 'wcf_runtime_range_filters' || block.id === 'wcf_range_filters_data') return;
        if (block.closest('#wcf_runtime_range_filters') || block.closest('#wcf_range_filters_data')) return;
        if (block.querySelector && block.querySelector('#o_wsale_price_range_option_inner')) return;

        // Doble seguridad: clase CSS + estilo inline con prioridad.
        // Esto evita que otro JS del tema/Odoo vuelva a dejar visible el header nativo.
        block.classList.add('wcf-native-range-hidden');
        block.setAttribute('data-wcf-native-range-hidden', '1');
        if (block.style && block.style.setProperty) {
            block.style.setProperty('display', 'none', 'important');
        }
    }

    function getDirectTitleText(block) {
        if (!block || !block.querySelector) return '';
        var titleNode = block.querySelector('.accordion-header .accordion-button b, .accordion-header .accordion-button strong, .accordion-header .accordion-button, h6 b, h6 strong, h6');
        return normalizeText(titleNode ? titleNode.textContent : '');
    }

    function looksLikeNativePriceRange(block) {
        if (!block || !block.querySelector) return false;
        if (block.querySelector('#o_wsale_price_range_option_inner')) return true;
        if (block.id === 'o_wsale_price_range_option_inner') return true;
        return getDirectTitleText(block) === normalizeText('Rango de precio');
    }

    function findClosestNativeFilterBlockFromTitleNode(node) {
        if (!node || !node.closest) return null;
        if (node.closest('#wcf_runtime_range_filters') || node.closest('#wcf_range_filters_data')) return null;

        var accordionItem = node.closest('.accordion-item');
        if (accordionItem) return accordionItem;

        var current = node;
        for (var i = 0; i < 8 && current; i++) {
            if (current.id === 'wcf_runtime_range_filters' || current.id === 'wcf_range_filters_data') return null;
            if (current.classList && (
                current.classList.contains('o_wsale_attribute') ||
                current.classList.contains('css_attribute_select') ||
                current.classList.contains('js_attribute') ||
                current.classList.contains('border-bottom')
            )) return current;
            current = current.parentElement;
        }
        return null;
    }

    function getNativeAttributeFieldValues(field) {
        if (!field) return [];
        if (field.tagName && field.tagName.toLowerCase() === 'select') {
            return Array.prototype.slice.call(field.options || []).map(function (option) {
                return option.value || '';
            });
        }
        return [field.value || ''];
    }

    function nativeAttributeFieldBelongsToItem(field, item) {
        var prefix = String(item.id) + '-';
        return getNativeAttributeFieldValues(field).some(function (value) {
            return String(value).indexOf(prefix) === 0;
        });
    }

    function hasNativeRangeAttributeFields(item) {
        // Esta comprobación replica el criterio de Odoo para la categoría actual:
        // si Odoo no ha renderizado ningún input/select del atributo, significa que
        // ningún producto visible de esa categoría/listado tiene valores para él.
        // En ese caso NO debemos crear el slider custom.
        return Array.prototype.slice.call(document.querySelectorAll('[name="attrib"], [name="attribute_value"]')).some(function (field) {
            return nativeAttributeFieldBelongsToItem(field, item);
        });
    }

    function getAvailableSources(sources) {
        return (sources || []).filter(function (item) {
            return hasNativeRangeAttributeFields(item);
        });
    }

    function collectNativeRangeAttributeBlocksForItem(item) {
        var found = [];

        function add(block) {
            if (!block || !block.querySelector) return;
            if (block.id === 'wcf_runtime_range_filters' || block.id === 'wcf_range_filters_data') return;
            if (block.closest('#wcf_runtime_range_filters') || block.closest('#wcf_range_filters_data')) return;
            if (block.querySelector('.wcf-range-slider')) return;
            if (looksLikeNativePriceRange(block)) return;
            if (found.indexOf(block) === -1) found.push(block);
        }

        if (!item) return found;

        var wantedName = normalizeText(item.name);

        // 1) Método principal: buscar campos nativos name="attrib" o
        // name="attribute_value" cuyo value pertenece al atributo range real.
        // Es también lo que decide si el slider custom debe existir en esta categoría.
        Array.prototype.slice.call(document.querySelectorAll('[name="attrib"], [name="attribute_value"]')).forEach(function (field) {
            if (nativeAttributeFieldBelongsToItem(field, item)) add(getNativeAttributeBlock(field));
        });

        // 2) Fallback por bloque: solo se usa para ocultar bien el bloque nativo
        // cuando ya sabemos que Odoo sí ha renderizado el atributo en la página.
        Array.prototype.slice.call(document.querySelectorAll('.accordion-item, .o_wsale_attribute, .css_attribute_select, .js_attribute, .mb-3, .border-bottom')).forEach(function (block) {
            if (!block || !block.querySelector) return;
            if (getDirectTitleText(block) === wantedName) add(block);
        });

        // 3) Fallback fuerte por nodo de texto: igual que el anterior, pero nunca
        // decide por sí solo que el slider deba mostrarse.
        Array.prototype.slice.call(document.querySelectorAll('h1,h2,h3,h4,h5,h6,button,b,strong,label,span')).forEach(function (node) {
            if (!node || !node.closest) return;
            if (node.closest('#wcf_runtime_range_filters') || node.closest('#wcf_range_filters_data')) return;
            if (normalizeText(node.textContent) !== wantedName) return;
            add(findClosestNativeFilterBlockFromTitleNode(node));
        });

        found.sort(function (a, b) {
            if (a === b) return 0;
            return a.compareDocumentPosition(b) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1;
        });
        return found;
    }

    function collectNativeRangeAttributeBlocks(sources) {
        var found = [];
        (sources || []).forEach(function (item) {
            collectNativeRangeAttributeBlocksForItem(item).forEach(function (block) {
                if (found.indexOf(block) === -1) found.push(block);
            });
        });
        found.sort(function (a, b) {
            if (a === b) return 0;
            return a.compareDocumentPosition(b) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1;
        });
        return found;
    }

    function hideNativeRangeAttributeBlocks(sources, knownBlocks) {
        var blocks = knownBlocks || collectNativeRangeAttributeBlocks(sources);
        blocks.forEach(hideBlock);
        return blocks;
    }

    function renderRuntimeFilters() {
        if (!isShopPage()) {
            return;
        }
        cleanProductLinks();
        var allSources = getSources();
        if (!allSources.length) {
            return;
        }

        var sources = getAvailableSources(allSources);
        var existing = document.getElementById('wcf_runtime_range_filters');
        if (existing && existing.parentNode) existing.parentNode.removeChild(existing);

        // Si Odoo no ha renderizado ningún atributo range nativo para la
        // categoría/listado actual, no pintamos ningún slider custom.
        if (!sources.length) {
            replaceNativeClearFiltersButtons();
            return;
        }

        var params = new URLSearchParams(window.location.search);

        // Localizamos el/los bloques nativos ANTES de insertar el slider propio.
        // Así podemos poner el slider exactamente donde estaba el atributo nativo
        // y después ocultar el nativo sin depender del orden de carga del JS de Odoo.
        var nativeBlocks = collectNativeRangeAttributeBlocks(sources);
        var firstNativeBlock = nativeBlocks.length ? nativeBlocks[0] : null;
        var priceBlock = findPriceBlock();

        var wrapper = document.createElement('div');
        wrapper.id = 'wcf_runtime_range_filters';
        sources.forEach(function (item) {
            wrapper.appendChild(buildBlock(item, params));
        });

        if (firstNativeBlock && firstNativeBlock.parentNode) {
            firstNativeBlock.parentNode.insertBefore(wrapper, firstNativeBlock);
        } else if (priceBlock && priceBlock.parentNode) {
            priceBlock.parentNode.insertBefore(wrapper, priceBlock);
        } else {
            var fallback = document.querySelector('form.js_attributes') || document.querySelector('#products_grid_before') || document.querySelector('.o_wsale_products_grid_before');
            if (fallback) fallback.insertBefore(wrapper, fallback.firstChild);
        }

        hideNativeRangeAttributeBlocks(sources, nativeBlocks);
        replaceNativeClearFiltersButtons();
    }

    function refreshOnlyNativeHiding() {
        if (!isShopPage()) {
            return;
        }
        cleanProductLinks();
        replaceNativeClearFiltersButtons();
        var allSources = getSources();
        if (!allSources.length) {
            return;
        }
        var sources = getAvailableSources(allSources);
        var existing = document.getElementById('wcf_runtime_range_filters');
        var renderedIds = existing
            ? Array.prototype.slice.call(existing.querySelectorAll('.wcf-range-filter')).map(function (block) { return block.dataset.wcfAttributeId; }).join(',')
            : '';
        var availableIds = sources.map(function (item) { return String(item.id); }).join(',');

        if (!existing || renderedIds !== availableIds) {
            renderRuntimeFilters();
        } else {
            hideNativeRangeAttributeBlocks(sources);
        }
    }

    function setupMutationObserver() {
        if (!window.MutationObserver) {
            return;
        }
        var target = document.querySelector('form.js_attributes') || document.querySelector('#products_grid_before') || document.querySelector('.o_wsale_products_grid_before') || document.body;
        if (!target) {
            return;
        }
        var timer = null;
        var observer = new MutationObserver(function (mutations) {
            window.clearTimeout(timer);
            timer = window.setTimeout(refreshOnlyNativeHiding, 80);
        });
        observer.observe(target, { childList: true, subtree: true });
    }

    document.addEventListener('DOMContentLoaded', function () {
        cleanProductLinks();
        replaceNativeClearFiltersButtons();
        renderRuntimeFilters();
        setupMutationObserver();
    });
    window.addEventListener('load', function () {
        replaceNativeClearFiltersButtons();
        renderRuntimeFilters();
        refreshOnlyNativeHiding();
    });
    document.addEventListener('shown.bs.offcanvas', function () {
        replaceNativeClearFiltersButtons();
        refreshOnlyNativeHiding();
    });
    window.setTimeout(function () { renderRuntimeFilters(); }, 100);
    window.setTimeout(function () { refreshOnlyNativeHiding(); }, 500);
    window.setTimeout(function () { refreshOnlyNativeHiding(); }, 1200);
    window.setTimeout(function () { refreshOnlyNativeHiding(); }, 2500);

})();
